sql.insert:
INSERT INTO photo_layer_layouts (
  photo_variant_id, layer_type, position_x, position_y, rotation_degrees,
  scale_x, scale_y, sorting_order
) VALUES (
  @photo_variant_id, @layer_type, @position_x, @position_y, @rotation_degrees,
  @scale_x, @scale_y, @sorting_order
)
ON CONFLICT(photo_variant_id, layer_type) DO UPDATE SET
  position_x = excluded.position_x,
  position_y = excluded.position_y,
  rotation_degrees = excluded.rotation_degrees,
  scale_x = excluded.scale_x,
  scale_y = excluded.scale_y,
  sorting_order = excluded.sorting_order;
